from collections import Counter
def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row)
    bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]; objs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                comp=[]; st=[(r,c)]; seen[r][c]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr,b+dc
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]!=bg:
                            seen[x][y]=True; st.append((x,y))
                objs.append(comp)
    tmpl=[]; solo={}
    for comp in objs:
        colors={g[a][b] for a,b in comp}
        if len(colors)>=2: tmpl.append(comp); continue
        col=g[comp[0][0]][comp[0][1]]
        solo.setdefault(col,[]).append((comp[0][0],comp[0][1]))
    o=[row[:] for row in g]
    def stamp(shape,sr,sc):
        ok=True
        for dr,dc,v in shape:
            r,c=sr+dr,sc+dc
            if not(0<=r<H and 0<=c<W) or o[r][c]!=bg and o[r][c]!=v: ok=False;break
        if not ok: return False
        for dr,dc,v in shape: o[sr+dr][sc+dc]=v
        return True
    for comp in tmpl:
        marker=None
        for a,b in comp:
            if sum(1 for x,y in comp if g[x][y]==g[a][b])==1: marker=(a,b,g[a][b]); break
        if marker is None: continue
        mr,mc,mcol=marker
        rel=[(a-mr,b-mc) for a,b in comp if g[a][b]!=mcol]
        for (sr,sc) in solo[mcol]:
            if stamp([(a,b,g[a][b]) for a,b in rel],[sr,sc]): pass
    canon={'2':[( -1,-1),(0,-1),(1,-1),(1,0)],'3':[(1,0)]}
    stamps={'2':4,'3':7}
    for mcol,sl in canon.items():
        v=stamps[mcol]
        for (sr,sc) in solo.get(mcol,[]):
            sh=[(dr,dc,v) for dr,dc,_ in sl]
            if stamp(sh,sr,sc): pass
    return o
