def comps8(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in g]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            rr,cc=a+dr,b+dc
                            if 0<=rr<H and 0<=cc<W and g[rr][cc]!=bg and not seen[rr][cc]:
                                seen[rr][cc]=True; st.append((rr,cc))
                out.append(cells)
    return out
