def solve(i, verbose=False):
    gi=G[f'Demo pair {i} input']; go=G[f'Demo pair {i} output']
    H,W=len(gi),len(gi[0])
    cnt=Counter(x for row in gi for x in row); bg=cnt.most_common(1)[0][0]
    cs=comps8(gi,bg)
    seeds=[]; markers=[]
    for s in cs:
        if len(s)>1:
            rare=min(set(gi[a][b] for a,b in s),key=lambda v:sum(1 for a,b in s if gi[a][b]==v))
            anch=[(a,b) for a,b in s if gi[a][b]==rare][0]
            rel=[(a-anch[0],b-anch[1],gi[a][b]) for a,b in s]
            seeds.append((rare,rel))
        else: markers.append((s[0][0],s[0][1],gi[s[0][0]][s[0][1]]))
    D={(r,c):go[r][c] for r in range(H) for c in range(W) if gi[r][c]!=go[r][c]}
    sols=[]
    def bt(k,cover,path):
        if k==len(markers):
            if cover==D: sols.append(path.copy())
            return
        mr,mc,col=markers[k]
        opts=[]
        for si,(srare,srel) in enumerate(seeds):
            if srare!=col: continue
            anc=[(a,b) for a,b,p in srel if p==srare][0]
            body=[(a-anc[0],b-anc[1],p) for a,b,p in srel if p!=srare]
            for nme,tf in TFS.items():
                cells={((mr)+tf((a,b))[0],(mc)+tf((a,b))[1]):p for a,b,p in body}
                # must not overwrite existing non-bg input, and every painted cell must be a diff cell of this color OR the marker
                ok=True
                for (r,c),pv in cells.items():
                    if (r,c)==(mr,mc): continue
                    if gi[r][c]!=bg: ok=False;break
                    if pv!=D.get((r,c),None): ok=False;break
                if ok: opts.append((si,nme,frozenset(cells)))
        for o in opts:
            if o[2]|cover==D or (o[2]&cover)==o[2]:
                pass
            if cover | o[2] == D:
                bt(k+1,cover|o[2],path+[o])
    bt(0,set(),[])
    print('demo',i,'solutions:',len(sols),[( (m[0],m[1]),(s[1],s[0])) for m,s in sols[:2]])
